<?php
require_once __DIR__ . '/includes/visitor_portal.php';$pdo=db();$visitor=current_visitor($pdo);$q=trim($_GET['q']??'');$cat=trim($_GET['category']??'');$where=['b.deleted_at IS NULL','b.status="Available"'];$params=[];if($q!==''){$where[]='(b.title LIKE ? OR b.author LIKE ? OR b.isbn LIKE ? OR b.category_name LIKE ?)';$params=array_fill(0,4,'%'.$q.'%');}if($cat!==''){$where[]='b.category_name=?';$params[]=$cat;}$s=$pdo->prepare('SELECT b.* FROM books b WHERE '.implode(' AND ',$where).' ORDER BY b.title');$s->execute($params);$books=$s->fetchAll();$cats=$pdo->query('SELECT DISTINCT category_name FROM books WHERE deleted_at IS NULL ORDER BY category_name')->fetchAll(PDO::FETCH_COLUMN);visitor_portal_header('Browse Books',$visitor);
?><h2>Browse Books</h2><p class="text-muted">Books are released only after librarian review.</p><form class="row g-2 mb-3"><div class="col-md-6"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search title, author, ISBN, or category"></div><div class="col-md-4"><select class="form-select" name="category"><option value="">All categories</option><?php foreach($cats as $c):?><option<?= $cat===$c?' selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-success w-100">Search</button></div></form><div class="row g-3"><?php foreach($books as $b):?><div class="col-md-6 col-xl-4"><div class="card h-100 shadow-sm"><?php if($b['cover_file']):?><img src="<?=e($b['cover_file'])?>" class="card-img-top" style="height:200px;object-fit:cover" alt="Book cover"><?php endif;?><div class="card-body"><h5><?=e($b['title'])?></h5><p class="small text-muted mb-2"><?=e($b['author'])?></p><p class="small mb-2">Category: <?=e($b['category_name'])?><br>ISBN: <?=e($b['isbn']?:'—')?><br>Call no.: <?=e(trim(($b['floor_no']??'').' '.($b['section_name']??'').' '.($b['shelf_no']??'')))?:'—'?></p><span class="badge bg-success">Available</span><a class="btn btn-outline-success btn-sm float-end" href="guest_borrow_request.php?book_id=<?=(int)$b['id']?>">Request to Borrow</a></div></div></div><?php endforeach;?><?php if(!$books):?><p class="text-muted">No available books found.</p><?php endif;?></div><?php visitor_portal_footer(); ?>
